import{_ as o,o as t,c as a,ae as l}from"./chunks/framework.B3uLoxsb.js";const m=JSON.parse('{"title":"Source: docs/WORKFLOW_CONTRACT.md","description":"","frontmatter":{},"headers":[],"relativePath":"pt/reference/source/workflow-contract.md","filePath":"pt/reference/source/workflow-contract.md","lastUpdated":1771052491000}'),i={name:"pt/reference/source/workflow-contract.md"};function c(r,e,s,n,d,p){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="source-docs-workflow-contract-md" tabindex="-1">Source: docs/WORKFLOW_CONTRACT.md <a class="header-anchor" href="#source-docs-workflow-contract-md" aria-label="Permalink to &quot;Source: docs/WORKFLOW_CONTRACT.md&quot;">​</a></h1><h1 id="workflow-contract" tabindex="-1">Workflow Contract <a class="header-anchor" href="#workflow-contract" aria-label="Permalink to &quot;Workflow Contract&quot;">​</a></h1><p>The repository has two explicit workflow tracks:</p><ol><li><code>codex-native</code> track (default runtime and references)</li><li><code>compatibility</code> track (opt-in pack)</li></ol><h2 id="codex-native-contract" tabindex="-1">Codex-native contract <a class="header-anchor" href="#codex-native-contract" aria-label="Permalink to &quot;Codex-native contract&quot;">​</a></h2><p>The following locations must stay byte-aligned:</p><ol><li><code>skills/codex-workflows/references/workflows/*.md</code></li><li><code>skills/codex-workflows/templates/codex-native/.agent/workflows/*.md</code></li></ol><p>Rules:</p><ul><li>same filename set in both locations;</li><li>same content checksum in both locations;</li><li>all 13 workflow contracts present.</li></ul><h2 id="compatibility-contract" tabindex="-1">Compatibility contract <a class="header-anchor" href="#compatibility-contract" aria-label="Permalink to &quot;Compatibility contract&quot;">​</a></h2><p>The following locations must stay byte-aligned:</p><ol><li><code>skills/codex-workflows/templates/.agent/workflows/*.md</code></li><li><code>skills/codex-workflows/packs/antigravity-compat/.agent/workflows/*.md</code></li></ol><p>Rules:</p><ul><li>same filename set in both locations;</li><li>same content checksum in both locations;</li><li>compatibility mode only via <code>--profile antigravity-compat</code>.</li></ul><h2 id="differentiation-contract" tabindex="-1">Differentiation contract <a class="header-anchor" href="#differentiation-contract" aria-label="Permalink to &quot;Differentiation contract&quot;">​</a></h2><p>Codex-native workflows must remain clearly distinct from compatibility workflows.</p><p>Rules:</p><ul><li>non-identical content per workflow;</li><li>required codex-native structure sections present;</li><li>max similarity ratio versus compatibility baseline must stay below threshold.</li></ul><h2 id="rules-coverage-contract" tabindex="-1">Rules coverage contract <a class="header-anchor" href="#rules-coverage-contract" aria-label="Permalink to &quot;Rules coverage contract&quot;">​</a></h2><p>Codex-native workflow contracts require explicit layered rules coverage.</p><p>Rules:</p><ul><li><code>skills/codex-workflows/templates/codex-native/.agent/rules/CODEX.md</code> must exist;</li><li><code>rules/global/*.md</code> and <code>rules/domains/*.md</code> must meet minimum quality thresholds;</li><li>each workflow in <code>workflows/*.md</code> must have a matching file in <code>rules/workflows/*.md</code>.</li></ul><h2 id="validation-commands" tabindex="-1">Validation commands <a class="header-anchor" href="#validation-commands" aria-label="Permalink to &quot;Validation commands&quot;">​</a></h2><p>Split parity check:</p><p><code>python skills/codex-workflows/scripts/check_workflow_parity.py --references skills/codex-workflows/references/workflows --native skills/codex-workflows/templates/codex-native/.agent/workflows --template skills/codex-workflows/templates/.agent/workflows --pack skills/codex-workflows/packs/antigravity-compat/.agent/workflows</code></p><p>Codex-native quality and anti-copy gate:</p><p><code>python skills/codex-workflows/scripts/check_codex_native_quality.py --native skills/codex-workflows/templates/codex-native/.agent/workflows --compat skills/codex-workflows/packs/antigravity-compat/.agent/workflows --max-similarity 0.35</code></p><p>Codex-native layered rules gate:</p><p><code>python skills/codex-workflows/scripts/check_codex_native_rules.py --native-root skills/codex-workflows/templates/codex-native/.agent</code></p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>This contract keeps compatibility stable for opt-in users while protecting the default codex-native experience from copy-like drift.</p>',31)])])}const f=o(i,[["render",c]]);export{m as __pageData,f as default};
